<script setup lang="ts">
import { computed, onUnmounted, ref, shallowRef, watch } from 'vue'
import { previewResource, submitResource, resourceKind, type ResourcePlan, type ResourceIntent } from '../../api/resource-management'
import { workspaceError, type WorkspaceMeta } from '../../api/workspace'
import type { Topic } from '../../api/kafkaops'
import ResourceOperations from './ResourceOperations.vue'
const props=defineProps<{clusterId:string;topic:Topic;meta:WorkspaceMeta;actorId:string;showOperations?:boolean;action?:'topic_delete';hideDelete?:boolean}>()
const emit=defineEmits<{changed:[];submitted:[]}>()
const kind=shallowRef<'topic_delete'|'reassign'|'reassign_cancel'>(props.action??'reassign'),confirmation=shallowRef(''),rows=ref<{partition:number;replicas:string;cancel:boolean}[]>([]),plan=shallowRef<ResourcePlan>(),confirmed=shallowRef(false),busy=shallowRef(false),error=shallowRef(''),submitted=shallowRef(false),refreshVersion=shallowRef(0)
let epoch=0,disposed=false,draftEpoch=0
const allowed=computed(()=>props.meta.permissions.topic_manage&&props.meta.write_enabled&&!props.topic.internal)
const valid=computed(()=>allowed.value&&(kind.value==='topic_delete'?confirmation.value===props.topic.name:kind.value==='reassign_cancel'?rows.value.some(r=>r.cancel):rows.value.length>0&&rows.value.every(r=>/^\d+(\s*,\s*\d+)*$/.test(r.replicas)&&new Set(r.replicas.split(',').map(Number)).size===r.replicas.split(',').length)))
function invalidate(){++draftEpoch;plan.value=undefined;confirmed.value=false;submitted.value=false}
watch([kind,confirmation,rows],invalidate,{deep:true})
watch(()=>[props.clusterId,props.topic.name],()=>{++epoch;busy.value=false;error.value='';confirmation.value='';rows.value=(props.topic.partitions??[]).map(p=>({partition:p.partition,replicas:p.replicas.join(', '),cancel:false}));invalidate()},{immediate:true,flush:'sync'})
async function preview(){if(!valid.value||busy.value)return;const token=epoch;busy.value=true;error.value='';invalidate();const draft=draftEpoch;const input:ResourceIntent={kind:kind.value,resource:{type:'TOPIC',name:props.topic.name},...(kind.value==='topic_delete'?{confirmation_name:confirmation.value}:kind.value==='reassign'?{assignments:rows.value.map(r=>({partition:r.partition,replicas:r.replicas.split(',').map(Number)}))}:{partitions:rows.value.filter(r=>r.cancel).map(r=>r.partition)})};try{const result=await previewResource(props.clusterId,input);if(token===epoch&&!disposed&&draft===draftEpoch)plan.value=result}catch(e){if(token===epoch&&!disposed)error.value=workspaceError(e)}finally{if(token===epoch&&!disposed)busy.value=false}}
async function submit(){if(!plan.value||!confirmed.value||busy.value||submitted.value)return;const token=epoch;busy.value=true;submitted.value=true;try{await submitResource(props.clusterId,plan.value,globalThis.crypto.randomUUID());if(token===epoch&&!disposed){plan.value=undefined;refreshVersion.value++;emit('changed');emit('submitted')}}catch(e){if(token===epoch&&!disposed)error.value=workspaceError(e)}finally{if(token===epoch&&!disposed)busy.value=false}}
onUnmounted(()=>{disposed=true;++epoch})
</script>
<template><section class="topic-lifecycle"><h3>{{ kind==='topic_delete'?'删除 Topic':'副本调整' }}</h3><p v-if="topic.internal">内部 Topic 的删除与副本操作已禁用。</p><p v-if="error" role="alert">{{ error }}</p><form @submit.prevent="preview"><label v-if="!action">操作 <select v-model="kind" :disabled="busy"><option value="reassign">调整分区副本</option><option value="reassign_cancel">取消副本迁移</option><option v-if="!hideDelete" value="topic_delete">删除 Topic</option></select></label><template v-if="kind==='topic_delete'"><p>删除 Topic 会删除数据。请输入完整名称 {{ topic.name }} 确认目标。</p><label>确认 Topic 名称 <input v-model="confirmation" :disabled="!allowed||busy" aria-label="确认 Topic 名称" autocomplete="off"></label></template><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>分区</th><th>{{ kind==='reassign'?'目标副本 Broker ID（逗号分隔）':'选择取消迁移' }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.partition"><td>{{ row.partition }}</td><td><input v-if="kind==='reassign'" v-model="row.replicas" :disabled="!allowed||busy" :aria-label="`分区 ${row.partition} 目标副本`"><input v-else v-model="row.cancel" :disabled="!allowed||busy" type="checkbox" :aria-label="`取消分区 ${row.partition} 迁移`"></td></tr></tbody></table></div><p v-if="kind==='reassign'">第一个 Broker 为首选 Leader。</p><button :disabled="!valid||busy||submitted">预览并校验</button></form><section v-if="plan" class="lifecycle-preview panel"><h4>{{ plan.input.resource.name }} · {{ resourceKind(plan.input.kind) }}</h4><ul><li v-for="a in plan.input.assignments" :key="a.partition">分区 {{ a.partition }} → {{ a.replicas.join(', ') }}</li></ul><p v-if="plan.input.kind==='topic_delete'">确认删除 {{ plan.input.resource.name }} 及其数据。</p><label><input v-model="confirmed" type="checkbox">我已核对变更范围及影响</label><button :disabled="busy||!confirmed||submitted" @click="submit">提交变更申请</button></section><ResourceOperations v-if="showOperations!==false" :resource="{type:'TOPIC',name:topic.name}" :cluster-id="clusterId" :meta="meta" :actor-id="actorId" :refresh-version="refreshVersion" @changed="emit('changed')" /></section></template>
<style scoped>.topic-lifecycle{display:grid;gap:16px}.topic-lifecycle p{font-size:13px;color:#64748b}.lifecycle-preview{padding:16px}.topic-lifecycle form{display:grid;gap:14px}.topic-lifecycle form>button{justify-self:start}h3,h4{margin:0}</style>
